style.css:
@-moz-document domain("youtube.com") {
/* Main background */
    body, html {
       background-image: url("https://i.ibb.co/abcd1234/cutecat.png");

        background-size: cover !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        background-position: center !important;
    }

    /* Remove white/black overlays */
    ytd-app,
    #content,
    #page-manager,
    #primary,
    #secondary,
    ytd-watch-flexy,
    ytd-browse,
    ytd-page-manager,
    .ytd-page-manager {
        background: transparent !important;
    }
}
